#!/usr/bin/env python3
"""Can the recogniser spell a Latin word out of its BPE vocabulary?

A token ending in '@@' continues into the next one; a token without it ends
the word. If a word cannot be segmented this way, the model physically cannot
emit it and will transliterate instead.
"""
import sys

TOKENS = "/home/Oliweitz/voice_models/tokens.txt"


def load():
    words = set()
    with open(TOKENS, encoding="utf-8") as fh:
        for line in fh:
            parts = line.split()
            if parts:
                words.add(parts[0])
    return words


def segments(word, vocab, max_pieces=6):
    """All ways to split `word` into continuing pieces + one final piece."""
    out = []

    def walk(rest, acc):
        if len(acc) > max_pieces or len(out) > 8:
            return
        if rest == "" and acc and not acc[-1].endswith("@@"):
            out.append(list(acc))
            return
        for end in range(1, len(rest) + 1):
            piece = rest[:end]
            if end < len(rest):
                tok = piece + "@@"
                if tok in vocab:
                    walk(rest[end:], acc + [tok])
            else:
                if piece in vocab:
                    walk("", acc + [piece])

    walk(word, [])
    return out


if __name__ == "__main__":
    vocab = load()
    print("vocabulary size: %d" % len(vocab))
    print()
    for word in ["openvela", "open", "vela", "hello", "okay"]:
        found = segments(word, vocab)
        if found:
            print("%-10s 可拼出,共 %d 种切法:" % (word, len(found)))
            for s in found[:3]:
                print("             %s   ->  %s" % (" + ".join(s), "".join(
                    x[:-2] if x.endswith("@@") else x for x in s)))
        else:
            print("%-10s ❌ 词表里拼不出来" % word)

